import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [subjects, setSubjects] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  
  const [formData, setFormData] = useState({ day: 'Monday', grade: '', subject_id: '', time_slot: '', teacher_id: '' });

  const fetchClasses = () => axios.get('http://localhost:8081/api/timetable').then(res => setClasses(res.data));
  
  useEffect(() => { 
      fetchClasses(); 
      axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
      axios.get('http://localhost:8081/api/view-subjects').then(res => setSubjects(res.data));
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/timetable', formData).then(() => { 
        fetchClasses(); 
        setShowForm(false);
        setFormData({ day: 'Monday', grade: '', subject_id: '', time_slot: '', teacher_id: '' });
    }).catch(() => alert("Error adding class!"));
  };

  const handleDelete = (id) => { 
      if(window.confirm("Are you sure you want to delete this class?")) {
          axios.delete(`http://localhost:8081/api/timetable/${id}`).then(() => fetchClasses()); 
      }
  };

  const filteredClasses = classes.filter(c => 
    (c.day || '').toLowerCase().includes(searchQuery.toLowerCase()) || 
    (c.grade || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
    (c.subject || '').toLowerCase().includes(searchQuery.toLowerCase()) ||
    (c.teacher || '').toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div style={{ padding: '30px', fontFamily: 'sans-serif', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      
      <div style={{ backgroundColor: '#fff', padding: '20px', borderRadius: '12px', boxShadow: '0 2px 10px rgba(0,0,0,0.05)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2 style={{ margin: 0, color: '#1e293b', fontSize: '20px', display: 'flex', alignItems: 'center', gap: '10px' }}>
            📅 Manage Class Timetable
          </h2>
          <div style={{ display: 'flex', gap: '15px' }}>
            <input type="text" placeholder="Search Grade, Subject or Teacher..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.searchInput} />
            <button onClick={() => setShowForm(true)} style={styles.primaryBtn}>+ Add New Class</button>
          </div>
        </div>

        <table style={{ width: '100%', marginTop: '20px', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #e2e8f0' }}>
              <th style={styles.th}>No.</th><th style={styles.th}>Day & Time</th><th style={styles.th}>Grade</th><th style={styles.th}>Subject</th><th style={styles.th}>Teacher</th><th style={styles.th}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredClasses.length > 0 ? filteredClasses.map((c, index) => (
              <tr key={c.id} style={{ borderBottom: '1px solid #f1f5f9' }}>
                <td style={styles.td}>{index + 1}</td>
                <td style={{...styles.td, fontWeight: 'bold', color: '#1e293b'}}>{c.day}<br/><span style={{fontSize: '12px', color: '#64748b', fontWeight: 'normal'}}>{c.time_slot}</span></td>
                <td style={{...styles.td, color: '#0369a1', fontSize: '13px'}}>{c.grade}</td>
                <td style={{...styles.td, fontWeight: 'bold', fontSize: '13px'}}>{c.subject}</td>
                <td style={{...styles.td, color: '#475569', fontSize: '13px'}}>{c.teacher}</td>
                <td style={styles.td}>
                  <button onClick={() => handleDelete(c.id)} style={styles.iconBtn}>🗑️</button>
                </td>
              </tr>
            )) : <tr><td colSpan="6" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8' }}>No classes scheduled yet.</td></tr>}
          </tbody>
        </table>
      </div>

      {showForm && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b' }}>➕ Add New Class</h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <div style={{ display: 'flex', gap: '10px' }}>
                <select value={formData.day} onChange={(e) => setFormData({...formData, day: e.target.value})} style={styles.input} required>
                  <option value="Monday">Monday</option><option value="Tuesday">Tuesday</option><option value="Wednesday">Wednesday</option><option value="Thursday">Thursday</option><option value="Friday">Friday</option><option value="Saturday">Saturday</option><option value="Sunday">Sunday</option>
                </select>
                <input type="text" placeholder="Time (03:00 PM - 05:00 PM)" value={formData.time_slot} onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required style={styles.input} />
              </div>
              
              <input type="text" placeholder="Grade (e.g. Grade 10)" value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} required style={styles.input} />
              
              <select value={formData.subject_id} onChange={(e) => setFormData({...formData, subject_id: e.target.value})} style={styles.input} required>
                <option value="">-- Select Subject --</option>
                {subjects.map(s => <option key={s.id} value={s.id}>{s.subject_name}</option>)}
              </select>
              
              <select value={formData.teacher_id} onChange={(e) => setFormData({...formData, teacher_id: e.target.value})} style={styles.input} required>
                <option value="">-- Select Teacher --</option>
                {teachers.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}
              </select>

              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={() => setShowForm(false)} style={styles.cancelBtn}>Cancel</button>
                <button type="submit" style={styles.saveBtn}>Save Class</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  searchInput: { padding: '8px 15px', borderRadius: '20px', border: '1px solid #cbd5e1', outline: 'none', width: '250px', fontSize: '13px', backgroundColor: '#f8fafc' },
  primaryBtn: { padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' },
  th: { padding: '12px 10px', color: '#64748b', fontWeight: 'bold', fontSize: '13px' },
  td: { padding: '15px 10px', fontSize: '14px', verticalAlign: 'top' },
  iconBtn: { background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  modal: { backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '450px', boxShadow: '0 20px 25px -5px rgba(0,0,0,0.1)' },
  input: { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc' },
  cancelBtn: { padding: '10px 20px', background: 'none', color: '#64748b', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' },
  saveBtn: { padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' }
};
